import os, base64, zlib
R="LockCOC" if os.path.isdir("LockCOC") else "."
def P(p): return os.path.join(R,p)
def rd(p): return open(P(p),encoding="utf-8").read()
def w(p,s,m="w"): open(P(p),m,encoding="utf-8").write(s)
F={'srv.py': '', 'memories.html': '', 'memories.css': '', 'memories.js': '', 'daily.js': '', 'daily.css': '', 'grp': ''}
def D(k): return zlib.decompress(base64.b64decode(F[k])).decode("utf-8")
app=rd("app.py")
if "mem_onthisday" in app: raise SystemExit("[loi] da ap dung patch21 roi")
anchor="start_scheduler()\n\nif __name__"
if anchor not in app: raise SystemExit("[loi] khong thay vi tri chen trong app.py")
app=app.replace(anchor,D("srv.py")+"\n\n"+anchor,1); w("app.py",app)
w("templates/memories.html",D("memories.html")); w("static/memories.css",D("memories.css")); w("static/js/memories.js",D("memories.js")); w("static/js/daily.js",D("daily.js"))
c=rd("static/polish.css")
if ".daily-card" not in c: w("static/polish.css","\n"+D("daily.css"),"a")
t=rd("templates/index.html")
if "daily.js" not in t:
    a="  <script src=\"/static/js/nativemusic.js\"></script>"
    if a not in t: a="  <script src=\"/static/js/chatplus.js\"></script>"
    if a not in t: raise SystemExit("[loi] khong thay the script trong index.html (can patch13/19 truoc)")
    w("templates/index.html",t.replace(a,a+"\n  <script src=\"/static/js/daily.js\"></script>",1))
s=rd("static/js/social.js")
if "/memories" not in s:
    old='    el("a", { class: "row-item", href: "/library" }'
    new='    el("a", { class: "row-item", href: "/memories" }, icon("sparkle"), el("div", { class: "meta" }, el("strong", {}, "Kỷ niệm, phim và sao lưu"), el("small", {}, "Ngày này năm xưa, Wrapped, phim tự động, tải ZIP")), icon("chev", "i go")),\n'
    if old not in s: raise SystemExit("[loi] khong thay dong Thu vien trong social.js")
    w("static/js/social.js",s.replace(old,new+old,1))
e=rd("static/js/editor.js")
if "grp-bar" not in e:
    old='    const sh = bottomSheet(el("h3", { style: { margin: "0 0 4px" } }, "Gửi tới ai?"),\n'
    if old not in e: raise SystemExit("[loi] khong thay bang chon nguoi nhan trong editor.js")
    e=e.replace(old,D("grp")+old.replace('"Gửi tới ai?"),\n','"Gửi tới ai?"), grpBar,\n'),1)
    w("static/js/editor.js",e)
print("xong patch21")
